import React, { useCallback, useEffect, useMemo, useState } from "react";

const API_URL = (
  process.env.REACT_APP_API_URL || "http://localhost:5000"
).replace(/\/$/, "");

const AdminPanel = () => {
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState("");
  const [error, setError] = useState("");

  // ==========================================
  // Logout
  // ==========================================

  const logout = useCallback(() => {
    localStorage.removeItem("adminToken");
    window.location.href = "/admin/login";
  }, []);

  // ==========================================
  // API Request
  // ==========================================

  const apiRequest = useCallback(
    async (endpoint, options = {}) => {
      const token = localStorage.getItem("adminToken");

      if (!token) {
        logout();
        throw new Error("Authentication required");
      }

      const response = await fetch(`${API_URL}${endpoint}`, {
        ...options,
        headers: {
          ...(options.body
            ? { "Content-Type": "application/json" }
            : {}),
          ...(options.headers || {}),
          Authorization: `Bearer ${token}`,
        },
      });

      let data = {};

      try {
        data = await response.json();
      } catch {
        data = {};
      }

      if (response.status === 401 || response.status === 403) {
        localStorage.removeItem("adminToken");
        logout();
        throw new Error(
          "Your session has expired. Please login again."
        );
      }

      if (!response.ok) {
        throw new Error(
          data.error || "Something went wrong."
        );
      }

      return data;
    },
    [logout]
  );

  // ==========================================
  // Fetch Bookings
  // ==========================================

  const fetchBookings = useCallback(async () => {
    setLoading(true);
    setError("");

    try {
      const data = await apiRequest("/api/admin/bookings");

      console.log("Bookings API response:", data);

      let bookingList = [];

      if (Array.isArray(data)) {
        bookingList = data;
      } else if (Array.isArray(data.bookings)) {
        bookingList = data.bookings;
      } else if (Array.isArray(data.data)) {
        bookingList = data.data;
      }

      setBookings(bookingList);

      console.log(
        "Bookings loaded:",
        bookingList.length
      );
    } catch (err) {
      console.error("Fetch bookings error:", err);
      setBookings([]);
      setError(
        err.message || "Failed to fetch bookings."
      );
    } finally {
      setLoading(false);
    }
  }, [apiRequest]);

  // ==========================================
  // Initial Load
  // ==========================================

  useEffect(() => {
    const token = localStorage.getItem("adminToken");

    if (!token) {
      setLoading(false);
      return;
    }

    fetchBookings();
  }, [fetchBookings]);

  // ==========================================
  // Mark Booking Completed
  // ==========================================

  const markCompleted = async (id) => {
    if (!id) return;

    const confirmed = window.confirm(
      "Mark this booking as completed?"
    );

    if (!confirmed) return;

    setActionLoading(`complete-${id}`);
    setError("");

    try {
      await apiRequest(
        `/api/admin/bookings/${id}/complete`,
        {
          method: "PUT",
        }
      );

      await fetchBookings();
    } catch (err) {
      console.error(
        "Complete booking error:",
        err
      );

      setError(
        err.message ||
          "Failed to complete booking."
      );
    } finally {
      setActionLoading("");
    }
  };

  // ==========================================
  // Delete Booking
  // ==========================================

  const deleteBooking = async (id) => {
    if (!id) return;

    const confirmed = window.confirm(
      "Are you sure you want to permanently delete this booking?"
    );

    if (!confirmed) return;

    setActionLoading(`delete-${id}`);
    setError("");

    try {
      await apiRequest(
        `/api/admin/bookings/${id}`,
        {
          method: "DELETE",
        }
      );

      await fetchBookings();
    } catch (err) {
      console.error(
        "Delete booking error:",
        err
      );

      setError(
        err.message ||
          "Failed to delete booking."
      );
    } finally {
      setActionLoading("");
    }
  };

  // ==========================================
  // Export CSV
  // ==========================================

  const exportCSV = async () => {
    const token =
      localStorage.getItem("adminToken");

    if (!token) {
      logout();
      return;
    }

    setActionLoading("export");
    setError("");

    try {
      const response = await fetch(
        `${API_URL}/api/admin/bookings/export`,
        {
          method: "GET",
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      if (
        response.status === 401 ||
        response.status === 403
      ) {
        localStorage.removeItem("adminToken");
        logout();
        return;
      }

      if (!response.ok) {
        throw new Error(
          "Failed to export bookings."
        );
      }

      const blob = await response.blob();

      const downloadUrl =
        window.URL.createObjectURL(blob);

      const link =
        document.createElement("a");

      link.href = downloadUrl;
      link.download =
        "pest-control-bookings.csv";

      document.body.appendChild(link);
      link.click();
      link.remove();

      window.URL.revokeObjectURL(
        downloadUrl
      );
    } catch (err) {
      console.error(
        "Export error:",
        err
      );

      setError(
        err.message ||
          "Failed to export bookings."
      );
    } finally {
      setActionLoading("");
    }
  };

  // ==========================================
  // Statistics
  // ==========================================

  const statistics = useMemo(() => {
    const total = bookings.length;

    const completed = bookings.filter(
      (booking) => booking.completed === true
    ).length;

    const pending = total - completed;

    return {
      total,
      completed,
      pending,
    };
  }, [bookings]);

  // ==========================================
  // Format Date
  // ==========================================

  const formatDate = (date) => {
    if (!date) return "N/A";

    const parsedDate = new Date(date);

    if (Number.isNaN(parsedDate.getTime())) {
      return "Invalid date";
    }

    return parsedDate.toLocaleDateString(
      "en-IN",
      {
        day: "2-digit",
        month: "short",
        year: "numeric",
      }
    );
  };

  // ==========================================
  // Format Created Date
  // ==========================================

  const formatCreatedAt = (date) => {
    if (!date) return "N/A";

    const parsedDate = new Date(date);

    if (Number.isNaN(parsedDate.getTime())) {
      return "N/A";
    }

    return parsedDate.toLocaleString(
      "en-IN",
      {
        day: "2-digit",
        month: "short",
        year: "numeric",
        hour: "2-digit",
        minute: "2-digit",
      }
    );
  };

  // ==========================================
  // Check Login
  // ==========================================

  const token =
    localStorage.getItem("adminToken");

  if (!token) {
    return (
      <div className="min-h-screen flex items-center justify-center px-4 bg-gray-50">
        <div className="bg-white rounded-xl shadow-md p-8 text-center max-w-md w-full">

          <div className="text-5xl mb-4">
            🔐
          </div>

          <h1 className="text-2xl font-bold text-gray-900 mb-2">
            Admin Login Required
          </h1>

          <p className="text-gray-600 mb-6">
            Please login as an administrator
            to access the dashboard.
          </p>

          <a
            href="/admin/login"
            className="inline-block bg-primary text-white px-6 py-3 rounded-lg font-medium hover:opacity-90 transition"
          >
            Go to Admin Login
          </a>

        </div>
      </div>
    );
  }

  // ==========================================
  // Dashboard
  // ==========================================

  return (
    <div className="min-h-screen bg-gray-50 px-4 py-8">

      <div className="max-w-7xl mx-auto">

        {/* =====================================
            Header
        ===================================== */}

        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-8">

          <div>
            <p className="text-sm text-gray-500 mb-1">
              Pest Control Management
            </p>

            <h1 className="text-3xl font-bold text-gray-900">
              Admin Dashboard
            </h1>

            <p className="text-sm text-gray-500 mt-2">
              {bookings.length} booking
              {bookings.length !== 1
                ? "s"
                : ""} found
            </p>
          </div>

          <div className="flex flex-wrap gap-2">

            <button
              onClick={fetchBookings}
              disabled={loading}
              className="px-4 py-2 rounded-lg border border-gray-300 bg-white text-gray-700 font-medium hover:bg-gray-100 disabled:opacity-50 transition"
            >
              {loading
                ? "Refreshing..."
                : "↻ Refresh"}
            </button>

            <button
              onClick={exportCSV}
              disabled={
                actionLoading === "export" ||
                bookings.length === 0
              }
              className="px-4 py-2 rounded-lg bg-primary text-white font-medium hover:opacity-90 disabled:opacity-50 transition"
            >
              {actionLoading === "export"
                ? "Exporting..."
                : "Export CSV"}
            </button>

            <button
              onClick={logout}
              className="px-4 py-2 rounded-lg bg-gray-800 text-white font-medium hover:bg-gray-900 transition"
            >
              Logout
            </button>

          </div>
        </div>

        {/* =====================================
            Error
        ===================================== */}

        {error && (
          <div className="mb-6 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-red-700">

            <div className="flex items-start justify-between gap-4">

              <p>{error}</p>

              <button
                onClick={() => setError("")}
                className="font-bold text-lg"
              >
                ×
              </button>

            </div>
          </div>
        )}

        {/* =====================================
            Statistics
        ===================================== */}

        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-8">

          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-5">

            <p className="text-sm text-gray-500">
              Total Bookings
            </p>

            <p className="text-3xl font-bold text-gray-900 mt-2">
              {statistics.total}
            </p>

          </div>

          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-5">

            <p className="text-sm text-gray-500">
              Pending
            </p>

            <p className="text-3xl font-bold text-yellow-600 mt-2">
              {statistics.pending}
            </p>

          </div>

          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-5">

            <p className="text-sm text-gray-500">
              Completed
            </p>

            <p className="text-3xl font-bold text-green-600 mt-2">
              {statistics.completed}
            </p>

          </div>

        </div>

        {/* =====================================
            Loading
        ===================================== */}

        {loading ? (

          <div className="bg-white rounded-xl shadow-sm p-12 text-center">

            <div className="animate-spin w-10 h-10 border-4 border-gray-200 border-t-primary rounded-full mx-auto mb-4" />

            <p className="text-gray-600">
              Loading bookings...
            </p>

          </div>

        ) : bookings.length === 0 ? (

          /* ===================================
             Empty State
          =================================== */

          <div className="bg-white rounded-xl shadow-sm p-12 text-center">

            <div className="text-5xl mb-4">
              📋
            </div>

            <h2 className="text-xl font-semibold text-gray-900 mb-2">
              No bookings yet
            </h2>

            <p className="text-gray-500 mb-6">
              No bookings were returned by
              the server.
            </p>

            <button
              onClick={fetchBookings}
              className="px-5 py-2.5 bg-primary text-white rounded-lg font-medium hover:opacity-90"
            >
              Refresh Bookings
            </button>

          </div>

        ) : (

          <>
            {/* =================================
                Desktop Table
            ================================= */}

            <div className="hidden lg:block bg-white rounded-xl shadow-sm overflow-hidden">

              <div className="overflow-x-auto">

                <table className="w-full">

                  <thead>
                    <tr className="bg-gray-100 text-left text-sm text-gray-600">

                      <th className="px-4 py-4 font-semibold">
                        Customer
                      </th>

                      <th className="px-4 py-4 font-semibold">
                        Mobile
                      </th>

                      <th className="px-4 py-4 font-semibold">
                        Service
                      </th>

                      <th className="px-4 py-4 font-semibold">
                        Appointment
                      </th>

                      <th className="px-4 py-4 font-semibold">
                        Status
                      </th>

                      <th className="px-4 py-4 font-semibold">
                        Created
                      </th>

                      <th className="px-4 py-4 font-semibold">
                        Actions
                      </th>

                    </tr>
                  </thead>

                  <tbody className="divide-y divide-gray-100">

                    {bookings.map((booking) => {

                      const id = booking._id;

                      const isCompleting =
                        actionLoading ===
                        `complete-${id}`;

                      const isDeleting =
                        actionLoading ===
                        `delete-${id}`;

                      return (
                        <tr
                          key={id}
                          className={
                            booking.completed
                              ? "bg-green-50/50"
                              : "hover:bg-gray-50"
                          }
                        >

                          {/* Customer */}

                          <td className="px-4 py-4">

                            <div className="font-semibold text-gray-900">
                              {booking.fullName ||
                                "N/A"}
                            </div>

                            <div className="text-xs text-gray-500 mt-1 max-w-xs">
                              {booking.address ||
                                "N/A"}
                            </div>

                          </td>

                          {/* Mobile */}

                          <td className="px-4 py-4 text-gray-700">

                            <a
                              href={`tel:${booking.mobile}`}
                              className="hover:text-primary"
                            >
                              {booking.mobile ||
                                "N/A"}
                            </a>

                          </td>

                          {/* Service */}

                          <td className="px-4 py-4">

                            <span className="inline-flex px-2.5 py-1 rounded-full bg-blue-50 text-blue-700 text-xs font-medium">
                              {booking.service ||
                                "N/A"}
                            </span>

                          </td>

                          {/* Appointment */}

                          <td className="px-4 py-4">

                            <div className="font-medium text-gray-900">
                              {formatDate(
                                booking.preferredDate
                              )}
                            </div>

                            <div className="text-sm text-gray-500">
                              {booking.preferredTime ||
                                "N/A"}
                            </div>

                          </td>

                          {/* Status */}

                          <td className="px-4 py-4">

                            {booking.completed ? (

                              <span className="inline-flex px-2.5 py-1 rounded-full bg-green-100 text-green-700 text-xs font-semibold">
                                Completed
                              </span>

                            ) : (

                              <span className="inline-flex px-2.5 py-1 rounded-full bg-yellow-100 text-yellow-700 text-xs font-semibold">
                                Pending
                              </span>

                            )}

                          </td>

                          {/* Created */}

                          <td className="px-4 py-4 text-sm text-gray-500">
                            {formatCreatedAt(
                              booking.createdAt
                            )}
                          </td>

                          {/* Actions */}

                          <td className="px-4 py-4">

                            <div className="flex gap-2">

                              {!booking.completed && (

                                <button
                                  onClick={() =>
                                    markCompleted(
                                      id
                                    )
                                  }
                                  disabled={
                                    isCompleting ||
                                    isDeleting
                                  }
                                  className="px-3 py-2 rounded-lg bg-green-600 text-white text-xs font-medium hover:bg-green-700 disabled:opacity-50"
                                >
                                  {isCompleting
                                    ? "Updating..."
                                    : "Complete"}
                                </button>

                              )}

                              <button
                                onClick={() =>
                                  deleteBooking(
                                    id
                                  )
                                }
                                disabled={
                                  isCompleting ||
                                  isDeleting
                                }
                                className="px-3 py-2 rounded-lg bg-red-600 text-white text-xs font-medium hover:bg-red-700 disabled:opacity-50"
                              >
                                {isDeleting
                                  ? "Deleting..."
                                  : "Delete"}
                              </button>

                            </div>

                          </td>

                        </tr>
                      );
                    })}

                  </tbody>

                </table>

              </div>

            </div>

            {/* =================================
                Mobile / Tablet Cards
            ================================= */}

            <div className="lg:hidden space-y-4">

              {bookings.map((booking) => {

                const id = booking._id;

                const isCompleting =
                  actionLoading ===
                  `complete-${id}`;

                const isDeleting =
                  actionLoading ===
                  `delete-${id}`;

                return (
                  <div
                    key={id}
                    className={`bg-white rounded-xl shadow-sm border p-5 ${
                      booking.completed
                        ? "border-green-200"
                        : "border-yellow-200"
                    }`}
                  >

                    {/* Card Header */}

                    <div className="flex justify-between items-start gap-4 mb-4">

                      <div>

                        <h2 className="font-bold text-lg text-gray-900">
                          {booking.fullName ||
                            "N/A"}
                        </h2>

                        <a
                          href={`tel:${booking.mobile}`}
                          className="text-sm text-primary mt-1 inline-block"
                        >
                          {booking.mobile ||
                            "N/A"}
                        </a>

                      </div>

                      {booking.completed ? (

                        <span className="shrink-0 px-2.5 py-1 rounded-full bg-green-100 text-green-700 text-xs font-semibold">
                          Completed
                        </span>

                      ) : (

                        <span className="shrink-0 px-2.5 py-1 rounded-full bg-yellow-100 text-yellow-700 text-xs font-semibold">
                          Pending
                        </span>

                      )}

                    </div>

                    {/* Booking Information */}

                    <div className="space-y-3 text-sm">

                      <div>

                        <p className="text-gray-500">
                          Service
                        </p>

                        <p className="font-medium text-gray-900">
                          {booking.service ||
                            "N/A"}
                        </p>

                      </div>

                      <div>

                        <p className="text-gray-500">
                          Address
                        </p>

                        <p className="font-medium text-gray-900">
                          {booking.address ||
                            "N/A"}
                        </p>

                      </div>

                      <div className="grid grid-cols-2 gap-4">

                        <div>

                          <p className="text-gray-500">
                            Date
                          </p>

                          <p className="font-medium text-gray-900">
                            {formatDate(
                              booking.preferredDate
                            )}
                          </p>

                        </div>

                        <div>

                          <p className="text-gray-500">
                            Time
                          </p>

                          <p className="font-medium text-gray-900">
                            {booking.preferredTime ||
                              "N/A"}
                          </p>

                        </div>

                      </div>

                      <div>

                        <p className="text-gray-500">
                          Booking Created
                        </p>

                        <p className="font-medium text-gray-900">
                          {formatCreatedAt(
                            booking.createdAt
                          )}
                        </p>

                      </div>

                    </div>

                    {/* Actions */}

                    <div className="flex gap-2 mt-5">

                      {!booking.completed && (

                        <button
                          onClick={() =>
                            markCompleted(id)
                          }
                          disabled={
                            isCompleting ||
                            isDeleting
                          }
                          className="flex-1 px-3 py-2.5 rounded-lg bg-green-600 text-white text-sm font-medium hover:bg-green-700 disabled:opacity-50"
                        >
                          {isCompleting
                            ? "Updating..."
                            : "Mark Completed"}
                        </button>

                      )}

                      <button
                        onClick={() =>
                          deleteBooking(id)
                        }
                        disabled={
                          isCompleting ||
                          isDeleting
                        }
                        className="flex-1 px-3 py-2.5 rounded-lg bg-red-600 text-white text-sm font-medium hover:bg-red-700 disabled:opacity-50"
                      >
                        {isDeleting
                          ? "Deleting..."
                          : "Delete"}
                      </button>

                    </div>

                  </div>
                );
              })}

            </div>
          </>
        )}

      </div>
    </div>
  );
};

export default AdminPanel;
